import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 전표처리로 만드는 전표의 원천 구분은 AUTO, 상태는 승인, 전표일자는 처리 당일
const VOUCHER_SOURCE_TYPE = 'AUTO';
const VOUCHER_STATUS = '승인';
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr00905Controller {
  @Get('/loan-statements')
  async listLoanStatements(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const fromDate = String(query['fromDate'] ?? '');
    const toDate = String(query['toDate'] ?? '');
    const loanType = String(query['loanType'] ?? '');
    if (!DATE_PATTERN.test(fromDate) || !DATE_PATTERN.test(toDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (loanType !== 'BORROWING' && loanType !== 'LENDING') {
      throw new ApiError(400, 'VALIDATION_FAILED', '차입/대여 구분을 선택해 주세요.');
    }
    const partnerRaw = query['partnerId'];
    let partnerId: string | null = null;
    if (partnerRaw !== undefined && partnerRaw !== null && String(partnerRaw) !== '') {
      if (!/^\d+$/.test(String(partnerRaw))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '거래처 값이 올바르지 않습니다.');
      }
      partnerId = String(partnerRaw);
    }
    const pageRaw = query['page'] === undefined || query['page'] === '' ? '0' : String(query['page']);
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? '20' : String(query['size']);
    if (!/^\d+$/.test(pageRaw) || !/^\d+$/.test(sizeRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const page = Number(pageRaw);
    const size = Math.min(Math.max(Number(sizeRaw), 1), 200);
    return transaction(async (db) => {
      const range = await db.query(
        'SELECT CAST(:fromDate AS date) > CAST(:toDate AS date) AS "invalid"',
        { fromDate, toDate },
      );
      if (range[0]['invalid']) {
        throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 시작일이 종료일보다 늦을 수 없습니다.');
      }
      const params = { fromDate, toDate, loanType, partnerId, limit: size, offset: page * size };
      const items = await db.query(
        'SELECT loan_statement_id AS "loanStatementId", partner_id AS "partnerId", loan_type AS "loanType", '
        + 'occurrence_date AS "occurrenceDate", occurrence_amount AS "occurrenceAmount", '
        + 'repayment_amount AS "repaymentAmount", balance_amount AS "balanceAmount", '
        + 'is_voucher_processed AS "isVoucherProcessed" '
        + 'FROM loan_statement '
        + 'WHERE occurrence_date >= CAST(:fromDate AS date) AND occurrence_date <= CAST(:toDate AS date) '
        + 'AND loan_type = :loanType '
        + 'AND (CAST(:partnerId AS bigint) IS NULL OR partner_id = CAST(:partnerId AS bigint)) '
        + 'ORDER BY occurrence_date DESC, loan_statement_id DESC '
        + 'LIMIT :limit OFFSET :offset',
        params,
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM loan_statement '
        + 'WHERE occurrence_date >= CAST(:fromDate AS date) AND occurrence_date <= CAST(:toDate AS date) '
        + 'AND loan_type = :loanType '
        + 'AND (CAST(:partnerId AS bigint) IS NULL OR partner_id = CAST(:partnerId AS bigint))',
        { fromDate, toDate, loanType, partnerId },
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }

  @Post('/loan-statements/:loanStatementId/process-voucher')
  @HttpCode(200)
  async processLoanStatementVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const loanStatementId = req.params['loanStatementId'];
    if (!/^\d+$/.test(loanStatementId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '명세 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT loan_statement_id AS "loanStatementId", occurrence_amount AS "occurrenceAmount", '
        + 'is_voucher_processed AS "isVoucherProcessed" '
        + 'FROM loan_statement WHERE loan_statement_id = CAST(:loanStatementId AS bigint) FOR UPDATE',
        { loanStatementId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'LOAN_STATEMENT_NOT_FOUND', '명세 건을 찾을 수 없습니다.');
      }
      if (found[0]['isVoucherProcessed']) {
        throw new ApiError(409, 'LOAN_STATEMENT_ALREADY_PROCESSED', '이미 전표처리된 명세입니다.');
      }
      // 가정: 차변·대변 합계는 명세의 발생금액으로 둔다
      const created = await db.query(
        'INSERT INTO journal_voucher (voucher_date, source_type, status, debit_total, credit_total, created_at, updated_at) '
        + 'VALUES (CAST(now() AS date), :sourceType, :status, CAST(:amount AS numeric), CAST(:amount AS numeric), now(), now()) '
        + 'RETURNING journal_voucher_id AS "journalVoucherId"',
        { sourceType: VOUCHER_SOURCE_TYPE, status: VOUCHER_STATUS, amount: String(found[0]['occurrenceAmount']) },
      );
      if (created.length === 0) {
        throw new ApiError(422, 'VOUCHER_CREATION_FAILED', '전표 생성에 실패했습니다.');
      }
      const journalVoucherId = created[0]['journalVoucherId'];
      const changed = await db.execute(
        'UPDATE loan_statement SET journal_voucher_id = CAST(:journalVoucherId AS bigint), '
        + 'is_voucher_processed = true, updated_at = now() '
        + 'WHERE loan_statement_id = CAST(:loanStatementId AS bigint) AND is_voucher_processed = false',
        { journalVoucherId: String(journalVoucherId), loanStatementId },
      );
      if (changed === 0) {
        throw new ApiError(409, 'LOAN_STATEMENT_ALREADY_PROCESSED', '이미 전표처리된 명세입니다.');
      }
      return {
        loanStatementId: Number(loanStatementId),
        journalVoucherId: Number(journalVoucherId),
        isVoucherProcessed: true,
      };
    });
  }
}

