import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const LOAN_TYPES: [string, string][] = [
  ['BORROWING', '차입금'],
  ['LENDING', '대여금'],
];

const SIZE = 20;

export default function FnSfr00905Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [loanType, setLoanType] = useState('BORROWING');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | undefined>(undefined);
  const [pageNo, setPageNo] = useState(0);
  const [filterError, setFilterError] = useState('');
  const [target, setTarget] = useState<Row | undefined>(undefined);
  const [mode, setMode] = useState<'detail' | 'process' | ''>('');

  const { data, error, reload } = useData<Page>(async () => {
    if (!applied) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/loan-statements', role, undefined, { ...applied, page: pageNo, size: SIZE });
  }, [applied, pageNo, role]);

  const rows = data?.items ?? [];
  const pending = rows.filter((r) => !r['isVoucherProcessed']);
  const pendingAmount = pending.reduce((sum, r) => sum + Number(r['occurrenceAmount'] ?? 0), 0);

  const search = () => {
    if (!fromDate || !toDate) {
      setFilterError('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    if (fromDate > toDate) {
      setFilterError('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    if (!loanType) {
      setFilterError('차입/대여 구분을 선택해 주세요.');
      return;
    }
    setFilterError('');
    setPageNo(0);
    setApplied({ fromDate, toDate, loanType, partnerId });
  };

  const reset = () => {
    setFromDate('');
    setToDate('');
    setLoanType('BORROWING');
    setPartnerId('');
    setFilterError('');
    setApplied(undefined);
    setPageNo(0);
  };

  const close = () => {
    setMode('');
    setTarget(undefined);
  };

  const open = (row: Row, next: 'detail' | 'process') => {
    setTarget(row);
    setMode(next);
  };

  const submitVoucher = async () => {
    if (!target) {
      return;
    }
    await call('POST', '/loan-statements/' + String(target['loanStatementId']) + '/process-voucher', role, {});
    notify('전표처리를 했습니다.');
    close();
    reload();
  };

  const columns: Column[] = [
    { key: 'partnerId', label: '거래처', render: (r) => <RefName table="partner" role={role} value={r['partnerId']} /> },
    {
      key: 'loanType',
      label: '차입/대여 구분',
      render: (r) => <Badge value={r['loanType'] === 'BORROWING' ? '차입금' : '대여금'} />,
    },
    { key: 'occurrenceDate', label: '발생일자', render: (r) => <DateText value={r['occurrenceDate']} /> },
    { key: 'occurrenceAmount', label: '발생금액', render: (r) => <Num value={r['occurrenceAmount']} /> },
    { key: 'repaymentAmount', label: '상환금액', render: (r) => <Num value={r['repaymentAmount']} /> },
    { key: 'balanceAmount', label: '잔액', render: (r) => <Num value={r['balanceAmount']} /> },
    {
      key: 'isVoucherProcessed',
      label: '전표처리 여부',
      render: (r) => <Badge value={r['isVoucherProcessed'] ? '완료' : '대기'} />,
    },
    {
      key: 'action',
      label: '처리',
      render: (r) =>
        r['isVoucherProcessed'] ? null : (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              open(r, 'process');
            }}
          >
            전표처리
          </button>
        ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>명세서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label="차입/대여 구분" required>
            <Select value={loanType} onChange={setLoanType} options={LOAN_TYPES} />
          </Field>
          <Field label="거래처">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="전체" />
          </Field>
        </Filters>
        {filterError ? <ErrorText text={filterError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total ?? 0} />
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(r) => open(r, 'detail')}
          empty={applied ? '조회된 명세가 없습니다.' : '조회 조건을 입력하고 조회해 주세요.'}
        />
        <Pager page={pageNo} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        <Tiles
          items={[
            ['대기 건수', <Num value={pending.length} />],
            ['대기 발생금액', <Num value={pendingAmount} />],
          ]}
        />
      </section>
      {mode === 'detail' && target ? (
        <Drawer title="명세 상세" onClose={close}>
          <Pairs
            items={[
              ['거래처', <RefName table="partner" role={role} value={target['partnerId']} />],
              ['차입/대여 구분', <Badge value={target['loanType'] === 'BORROWING' ? '차입금' : '대여금'} />],
              ['발생일자', <DateText value={target['occurrenceDate']} />],
              ['발생금액', <Num value={target['occurrenceAmount']} />],
              ['상환금액', <Num value={target['repaymentAmount']} />],
              ['잔액', <Num value={target['balanceAmount']} />],
              ['전표처리 여부', <Badge value={target['isVoucherProcessed'] ? '완료' : '대기'} />],
            ]}
          />
          {target['isVoucherProcessed'] ? null : (
            <button type="button" onClick={() => setMode('process')}>
              전표처리
            </button>
          )}
        </Drawer>
      ) : null}
      {mode === 'process' && target ? (
        <Drawer title="전표처리" onClose={close}>
          <Form
            onSubmit={submitVoucher}
            submit="전표 생성"
            note={<span>선택한 명세 건의 전표를 생성하고 전표처리 여부를 반영합니다.</span>}
          >
            <Pairs
              items={[
                ['거래처', <RefName table="partner" role={role} value={target['partnerId']} />],
                ['발생일자', <DateText value={target['occurrenceDate']} />],
                ['발생금액', <Num value={target['occurrenceAmount']} />],
              ]}
            />
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
